scripts.杀手死亡.txt:
// 28个红衣杀手和黑衣杀手死亡

	Add($fight008, 1);
	If ($fight008 == 28) @finished;
    Return;
    
@finished:
	StopMusic();
	FadeOut();
	SetPlayerPos(13, 64);
	SetPlayerDir(6);
	SetNpcKind("张琳心", 1);
	SetNpcPos("张琳心", 12, 63);
	SetNpcDir("张琳心", 6);
	SetNpcKind("张琳心", 3);
	SetNpcPos("杀手头目", 14, 64);
	SetNpcDir("杀手头目", 2);
	Sleep(500);
	ClearEffect();
	FadeIn();
	
	Say("杀手头目：好小子！果真有两下子，难怪能够一路闯到这里来。",  111);
	Say("独孤剑：你们是五色教的杀手？", 5);
	Say("杀手头目：不错！", 111);
	Say("张琳心：你们为什么要血洗武夷山？", 27);
	Say("杀手头目：我们做杀手的，有钱就是娘，你要怪就怪我们教主方勉，是他接下这桩生意让我们来杀你的。", 111);
	Say("独孤剑：胡说！方、方大侠不会做出这样的事。", 9);
	Say("杀手头目：嘿，你已死到临头了，我又何必骗你，教主就是五色教的第一把剑，不信你去问阎王吧。", 111); 
	PlayMusic("激战.mp3");
	SetNpcRelation("杀手头目", 1);
	SetNpcDeathScript("杀手头目", "杀手头目死亡.txt");
	SetPlayerState(1);
    EnableFight();
	EnableNpcAI();
	SetMapTrap(1, "Trap01.txt");
	Assign($Event, 235);
	Return;

scripts.张琳心对话.txt:
// 张琳心同伴对话

	If ($Event >= 240) @Event240;
	Return;
	
@Event240:		
	Say("张琳心：柳伯伯似乎对我们两家的恩怨非常了解，只可惜他死了，否则可以好好问问他。", 28);
	Say("独孤剑：了解真相的人都死了，如今只有你爹，最清楚我们两家之间到底发生了什么事！", 1);
	Say("张琳心：我真想弄清楚到底发生了什么……", 28);
	Return;

scripts.杀手头目死亡.txt:
// 杀手头目死亡

	FadeOut();
	StopMusic();
	PlayMusic("前途.mp3");
	SetNpcKind("张琳心", 1);
	SetPlayerPos(18, 65);
	SetPlayerDir(5);
	SetPlayerState(0);
	SetNpcPos("张琳心", 19, 66);
	SetNpcDir("张琳心", 4);
	ClearEffect();
	FadeIn();
	
	Sleep(500);
	
	SetNpcActionFile("独孤剑", 0, "mpc007_2.asf");
	SetNpcActionFile("独孤剑", 1, "mpc007_2.asf");
	NpcSpecialAction("独孤剑", "mpc007_1.asf");    // 独孤剑蹲下
	Sleep(1500);
	Say("独孤剑：柳老前辈！", 6);
	Say("柳中原：是独孤少侠吗？看来、看来你师傅得到的是、是五色教的暗杀名单，快、快去长安通知顾枫。", 93);
	Say("独孤剑：那你——", 6);
	Say("柳中原：我、我不行了……", 93);
	Say("张琳心：柳伯伯，方勉真的是五色教第一把剑吗？", 25);
	Say("柳中原：绝无可能……还有……你们两家的恩、恩仇，其实……", 93);
	
	SetNpcActionFile("柳中原", 0, "mpc008_3.asf");
	SetNpcActionFile("柳中原", 1, "mpc008_3.asf");
	NpcSpecialAction("柳中原", "mpc008_2.asf");    //柳中原死亡
	Sleep(1500);
	DelNpc("柳中原"); 	//对存盘的处理
	AddNpc("死亡柳中原.ini", 19, 64, 1);
	SaveNpc();
	
	Say("独孤剑：柳老前辈！", 6);
	Say("张琳心：……", 24);
	

	SetNpcActionFile("独孤剑", 0, "npc001_st2.asf");
	SetNpcActionFile("独孤剑", 1, "npc001_sst2.asf");
	NpcSpecialAction("独孤剑", "mpc007_3.asf");    // 独孤剑站起	
	Sleep(1500);
	
	Watch("独孤剑", "张琳心", 0);
	Say("张琳心：柳前辈最后的话是想说什么呢？", 28);
	Say("独孤剑：现在恐怕没有人知道了，但无论如何，我一定会查个水落石出的。", 1);
	Say("张琳心：你现在打算去长安？", 24);
	Say("独孤剑：是的，我得赶快去找到顾大侠商量对策。", 1);
	Say("张琳心：我……我想和你一起去。", 21);
	Say("独孤剑：不行，五色教的人现在以为他们的暗杀名单在我身上，一定会沿路截杀，你跟着我太危险了。", 1);
	Say("张琳心：我，我就是知道此事关系到中原武林的安危，才想尽我的一份力。", 23);
	Say("独孤剑：这……", 8);
	Say("张琳心：你是不是因为……因为我父亲……", 27);
	Say("独孤剑：独孤剑一向恩怨分明，决不会因为父辈的仇怨而对张姑娘有什么成见。", 1);
	Say("张琳心：此去危机重重。我，担心你……你一个人应付不过来。是不是你觉得我是个累赘？那夜在碧霞岛……", 24);
	Say("独孤剑：没，没有……我不过是不想张姑娘卷入这场凶险的旋涡中。", 8);
	Say("张琳心：……柳前辈和这些杀手身上都没有血书，看来血书应该还在我爹那里，不如我们先回临安找我爹吧。", 28);
	Say("独孤剑：对！先找到血书要紧！", 1);

	SetNpcKind("张琳心", 3);
	SetNpcScript("张琳心", "张琳心对话.txt");
	SetMapTrap(1,"trap01.txt");
	Assign($Event, 240);
	Memo("两人进入禁地密洞，遇到五色教杀手，得知方勉竟是他们的幕后指使者。柳老前辈在临死之前让独孤剑前往华山派通知顾枫，他可能是下一个暗杀对象。");
	Memo("独孤剑和张琳心决定在去华山之前先到临安张风处取回血书。");
	Return;

